import {
  createBrowserRouter,
  RouterProvider,
  useParams,
  type RouteObject,
} from 'react-router';

export function UserView() {
  const { id } = useParams<{ id: string }>();
  return <p>user: {id}</p>;
}

export const routes: RouteObject[] = [
  { path: '/users/:id', element: <UserView /> },
];

export const router = createBrowserRouter(routes);

export function App() {
  return <RouterProvider router={router} />;
}
